def grid_transform(input_grid):
    # Find original 4 positions
    original_4s = set((r, c) for r in range(len(input_grid)) 
                     for c in range(len(input_grid[r])) 
                     if input_grid[r][c] == 4)

    # Create output grid as copy
    output_grid = [row[:] for row in input_grid]

    # If no original 4s, return as-is
    if not original_4s:
        return output_grid

    # 8-way BFS from all original 4 positions
    from collections import deque
    visited = set()
    q = deque()

    for (r, c) in original_4s:
        visited.add((r, c))
        q.append((r, c))

    while q:
        (r, c) = q.popleft()
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < len(input_grid) and 0 <= nc < len(input_grid[nr]):
                    if input_grid[nr][nc] == 0 and (nr, nc) not in visited:
                        visited.add((nr, nc))
                        output_grid[nr][nc] = 4
                        q.append((nr, nc))

    return output_grid

